{
  "implementation": "def solve(case):
    nodes = case['nodes']
    threshold = case['utility_threshold']

    # build parent->children mapping and node lookup
    children = {}
    node_dict = {}
    root_id = None
    for node in nodes:
        nid = node['id']
        node_dict[nid] = node
        parent = node['parent']
        if parent is None:
            root_id = nid
        else:
            children.setdefault(parent, []).append(nid)

    # sort children ids for deterministic order
    for parent in children:
        children[parent].sort()

    retained = []
    visit_order = []

    def dfs(nid):
        node = node_dict[nid]
        # prune if removable and below threshold
        if node['removable'] and node['utility'] < threshold:
            return
        retained.append(nid)
        visit_order.append(nid)
        for child in children.get(nid, []):
            dfs(child)

    dfs(root_id)
    return {
        'retained_node_ids': retained,
        'visit_order': visit_order
    }"
}
